package app.truemotion.vector;

import android.app.*;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import java.util.*;

/** Library, armature and JavaScript panels sharing the vector document's undo. */
final class VectorWorkspace {
    final VectorEditor editor;
    VectorWorkspace(VectorEditor e){editor=e;}
    void library(){VectorEditor e=editor;e.stop();e.stage.finishPen();ArrayList<String> titles=new ArrayList<String>();ArrayList<Runnable> actions=new ArrayList<Runnable>();
        add(titles,actions,L10n.t("Выделение → новый символ"),this::createSymbol);
        VectorDocument.Shape s=e.primary();if(s!=null&&s.isSymbol())add(titles,actions,L10n.t("Редактировать выбранный символ"),()->editSymbol(s.symbol));
        for(VectorSymbol symbol:e.doc.symbols.values())if(!symbol.id.equals(e.symbolContext))add(titles,actions,L10n.t("Вставить символ: ")+symbol.name,()->insert(symbol));
        new AlertDialog.Builder(e.activity).setTitle(L10n.t("Библиотека символов")).setItems(titles.toArray(new String[0]),(d,n)->actions.get(n).run()).setNegativeButton(L10n.t("Закрыть"),null).show();
    }
    static void add(List<String> names,List<Runnable> actions,String label,Runnable action){names.add(label);actions.add(action);}
    void createSymbol(){VectorEditor e=editor;if(e.selected.isEmpty()||!e.writable())return;LinearLayout box=e.box();EditText title=e.field(box,L10n.t("Имя символа"),L10n.t("Символ")+" "+(e.doc.symbols.size()+1),false);
        e.form(L10n.t("Новый символ"),box,()->{ArrayList<VectorDocument.Shape> artwork=new ArrayList<VectorDocument.Shape>();double left=Double.POSITIVE_INFINITY,top=left,right=Double.NEGATIVE_INFINITY,bottom=right;
            for(VectorDocument.Shape raw:e.cel().shapes)if(e.selected.contains(raw.id)){VectorDocument.Shape shape=e.doc.posed(raw,e.frame);artwork.add(shape);double[] b=e.doc.bounds(shape);for(double[] p:new double[][]{{b[0],b[1]},{b[2],b[1]},{b[2],b[3]},{b[0],b[3]}}){double[] xy=shape.world(p[0],p[1]);left=Math.min(left,xy[0]-shape.strokeWidth);right=Math.max(right,xy[0]+shape.strokeWidth);top=Math.min(top,xy[1]-shape.strokeWidth);bottom=Math.max(bottom,xy[1]+shape.strokeWidth);}}
            if(artwork.isEmpty())return;int w=Math.max(1,(int)Math.ceil(right-left+8)),h=Math.max(1,(int)Math.ceil(bottom-top+8));if(w>16384||h>16384)throw new IllegalArgumentException(L10n.t("Символ слишком большой"));double cx=(left+right)/2,cy=(top+bottom)/2;
            VectorDocument child=new VectorDocument(w,h,e.doc.fps,1);child.symbols=e.doc.symbols;child.images=e.doc.images;child.tracks.get(0).name=L10n.t("Рисунок 1");for(VectorDocument.Shape shape:artwork){shape.bone="";shape.x+=w/2d-cx;shape.y+=h/2d-cy;child.tracks.get(0).keys.get(0).shapes.add(shape);}
            VectorSymbol asset=new VectorSymbol(title.getText().toString(),child);e.snapshot();e.doc.symbols.put(asset.id,asset);e.edit().shapes.removeIf(s->e.selected.contains(s.id));VectorDocument.Shape instance=new VectorDocument.Shape();instance.name=asset.name;instance.symbol=asset.id;instance.x=cx;instance.y=cy;instance.symbolStart=e.doc.time(e.frame);e.edit().shapes.add(instance);e.selected.clear();e.selected.add(instance.id);e.refresh();
        });
    }
    void insert(VectorSymbol symbol){VectorEditor e=editor;if(!e.writable())return;e.snapshot();VectorDocument.Shape s=new VectorDocument.Shape();s.symbol=symbol.id;s.name=symbol.name;s.x=e.doc.width/2d;s.y=e.doc.height/2d;s.symbolStart=e.doc.time(e.frame);e.edit().shapes.add(s);e.selected.clear();e.selected.add(s.id);e.refresh();}
    void editSymbol(String id){VectorEditor e=editor;try{VectorDocument copy=VectorDocument.read(e.doc.json());VectorSymbol asset=copy.symbols.get(id);if(asset==null)return;VectorEditor child=new VectorEditor(e.activity,null,null,asset.document);child.parentEditor=e;child.symbolContext=id;child.editorTitle=L10n.t("Символ")+" · "+asset.name;child.commitHandler=changed->{copy.images.putAll(changed.images);for(VectorSymbol added:changed.symbols.values())if(!copy.symbols.containsKey(added.id))copy.symbols.put(added.id,added);copy.symbols.get(id).document=changed;for(VectorSymbol s:copy.symbols.values())s.document.symbols=copy.symbols;copy.validate();e.snapshot();e.doc.symbols=copy.symbols;e.doc.images=copy.images;e.refresh();};child.show();}catch(Exception error){e.error(error);}}
    void rigs(){VectorEditor e=editor;ArrayList<String> names=new ArrayList<String>();ArrayList<Runnable> actions=new ArrayList<Runnable>();add(names,actions,L10n.t("Рисовать и перемещать кости"),()->e.setTool(VectorEditor.BONE));add(names,actions,L10n.t("Создать цепь из двух костей"),this::chain);add(names,actions,L10n.t("Привязать выделение к кости"),this::bind);add(names,actions,L10n.t("Отвязать выделение от костей"),this::unbind);add(names,actions,L10n.t("Ключ позы костей"),()->{e.snapshot();e.doc.rig.edit(e.frame);e.refresh();});add(names,actions,L10n.t("IK: включить / выключить"),()->{e.boneIK=!e.boneIK;e.refresh();});add(names,actions,L10n.t("Изменить сторону сгиба IK"),()->{e.boneBend=!e.boneBend;e.refresh();});if(e.doc.rig.bones.containsKey(e.selectedBone))add(names,actions,L10n.t("Свойства выбранной кости"),this::boneProperties);new AlertDialog.Builder(e.activity).setTitle(L10n.t("Кости и IK")).setItems(names.toArray(new String[0]),(d,n)->actions.get(n).run()).show();}
    void chain(){VectorEditor e=editor;LinearLayout b=e.box();EditText one=e.field(b,L10n.t("Длина первой кости (пиксели)"),"100",true),two=e.field(b,L10n.t("Длина второй кости (пиксели)"),"80",true);e.form(L10n.t("Цепь из двух костей"),b,()->{double l1=e.number(one,1,100000),l2=e.number(two,1,100000);e.snapshot();VectorRig.Bone first=new VectorRig.Bone();first.name=L10n.t("Кость")+" "+(e.doc.rig.bones.size()+1);first.x=e.doc.width/2d;first.y=e.doc.height/2d;first.length=l1;e.doc.rig.bones.put(first.id,first);VectorRig.Bone last=new VectorRig.Bone();last.name=L10n.t("Кость")+" "+(e.doc.rig.bones.size()+1);last.parent=first.id;last.x=l1;last.length=l2;e.doc.rig.bones.put(last.id,last);e.selectedBone=last.id;e.doc.rig.edit(e.frame);e.setTool(VectorEditor.BONE);});}
    void bind(){VectorEditor e=editor;if(e.selected.isEmpty()||!e.writable())return;ArrayList<VectorRig.Bone> bones=new ArrayList<VectorRig.Bone>(e.doc.rig.bones.values());String[] names=new String[bones.size()];for(int i=0;i<names.length;i++)names[i]=bones.get(i).name;new AlertDialog.Builder(e.activity).setTitle(L10n.t("Кость для выделения")).setItems(names,(d,n)->{e.snapshot();String id=bones.get(n).id;double[] pose=e.doc.rig.world(id,e.frame);for(VectorDocument.Shape raw:e.edit().shapes)if(e.selected.contains(raw.id)){VectorDocument.Shape world=e.doc.posed(raw,e.frame);double[] local=e.doc.rig.inverse(id,e.frame,world.x,world.y);raw.bone=id;raw.x=local[0];raw.y=local[1];raw.angle=world.angle-pose[2];}e.selectedBone=id;e.refresh();}).show();}
    void unbind(){VectorEditor e=editor;if(e.selected.isEmpty()||!e.writable())return;e.snapshot();for(VectorDocument.Shape raw:e.edit().shapes)if(e.selected.contains(raw.id)){VectorDocument.Shape world=e.doc.posed(raw,e.frame);raw.bone="";raw.x=world.x;raw.y=world.y;raw.angle=world.angle;}e.refresh();}
    void boneProperties(){VectorEditor e=editor;VectorRig.Bone bone=e.doc.rig.bones.get(e.selectedBone);if(bone==null)return;double[] p=e.doc.rig.local(bone.id,e.frame);LinearLayout b=e.box();EditText name=e.field(b,L10n.t("Имя"),bone.name,false),length=e.field(b,L10n.t("Длина кости"),VectorDocument.n(bone.length),true),x=e.field(b,"X",VectorDocument.n(p[0]),true),y=e.field(b,"Y",VectorDocument.n(p[1]),true),angle=e.field(b,L10n.t("Поворот"),VectorDocument.n(p[2]),true);e.form(L10n.t("Кость слоя"),b,()->{double len=e.number(length,1,100000),px=e.number(x,-1000000,1000000),py=e.number(y,-1000000,1000000),a=e.number(angle,-1000000,1000000);e.snapshot();bone.length=len;bone.name=name.getText().toString();e.doc.rig.set(bone.id,e.frame,px,py,a);e.refresh();});}
    void script(){VectorEditor e=editor;e.stop();LinearLayout b=e.box();CheckBox enabled=new CheckBox(e.activity);enabled.setText(L10n.t("JavaScript включён"));enabled.setChecked(e.doc.scriptEnabled);b.addView(enabled);TextView help=new TextView(e.activity);help.setText(L10n.t("time — секунды, frame — номер кадра от 1, fps — частота. $('имя') или this.getChildByName('имя') возвращает объект. Доступны x, y, rotation, scaleX, scaleY, alpha, fill и nodes. Скрипт вычисляется отдельно для каждого кадра; для движения используйте time. Это JavaScript, не ActionScript."));b.addView(help);EditText code=e.field(b,L10n.t("Код кадра"),e.doc.script,false);code.setTypeface(android.graphics.Typeface.MONOSPACE);code.setMinLines(8);Button example=new Button(e.activity);example.setText(L10n.t("Пример JavaScript"));b.addView(example);example.setOnClickListener(v->code.setText("var obj = objects[0];\nif (obj) {\n  obj.x += Math.sin(time * Math.PI * 2) * 60;\n  obj.rotation += time * 30;\n}"));e.form(L10n.t("JavaScript кадра"),b,()->{VectorDocument probe=VectorDocument.read(e.doc.json());probe.script=code.getText().toString();probe.scriptEnabled=enabled.isChecked();if(probe.scriptEnabled)for(int f:new int[]{0,Math.min(probe.frames-1,e.frame)})probe.poseFrame(f);e.snapshot();e.doc.script=probe.script;e.doc.scriptEnabled=probe.scriptEnabled;e.refresh();});}
}
